record Tlv(int type, byte[] value) {}
static List<Tlv> parse(byte[] pdu) {
  var out = new ArrayList<Tlv>(); int i = 0;
  while (i + 2 <= pdu.length) {
    int h = ((pdu[i] & 0xff) << 8) | (pdu[i + 1] & 0xff);
    int type = h >>> 9, len = h & 0x1ff; i += 2;
    if (type == 0) break;                       // End of LLDPDU
    if (i + len > pdu.length) throw new IllegalArgumentException("uszkodzony TLV");
    out.add(new Tlv(type, Arrays.copyOfRange(pdu, i, i + len))); i += len;
  }
  return out;
}
